using System.ComponentModel.Composition;
using IFeatureMetadata = Microsoft.Dynamics.ApplicationPlatform.FeatureExposure.IFeatureMetadata;

/// <summary>
/// The <c>ConDemoFastPostingFeature</c> class exposes the fast posting behaviour in Feature management.
/// </summary>
[ExportAttribute(identifierStr(Microsoft.Dynamics.ApplicationPlatform.FeatureExposure.IFeatureMetadata))]
public final class ConDemoFastPostingFeature implements IFeatureMetadata
{
    private static ConDemoFastPostingFeature instance;

}

Method.Source:
private static void TypeNew()
{
    instance = new ConDemoFastPostingFeature();
}

/// <summary>
/// Gets the singleton instance of the <c>ConDemoFastPostingFeature</c> class.
/// </summary>
/// <returns>The singleton feature instance.</returns>
[Hookable(false)]
public static ConDemoFastPostingFeature instance()
{
    return ConDemoFastPostingFeature::instance;
}

/// <summary>
/// Determines whether the fast posting feature is enabled.
/// </summary>
/// <returns>true if the feature is enabled in Feature management; otherwise, false.</returns>
[Hookable(false)]
public static boolean isEnabled()
{
    return FeatureStateProvider::isFeatureEnabled(ConDemoFastPostingFeature::instance());
}
